diffs.patch:
Index: openwiki/.claims/architecture/overview.json
===================================================================
--- openwiki/.claims/architecture/overview.json	
+++ openwiki/.claims/architecture/overview.json	
@@ -0,0 +1,118 @@
+{
+  "schemaVersion": 1,
+  "pageVersion": "sha256:1e2c77999f95d0447bcadb8169b8a4bcfd5169969fdc8907aac96bad42f46741",
+  "claims": [
+    {
+      "id": "claim_dfbf3321bc01408688a347799e1d3755",
+      "statement": "step is a CLI toolkit for building, operating, and automating PKI and crypto workflows and a client for the step-ca online CA and any ACMEv2 CA.",
+      "evidence": [
+        {
+          "resource": "repo://README.md#L12-L14",
+          "version": "repo-lines-v1:sha256:097cc7c9943e58ff0a178feb261159a19aa9c0debec3f9d44ca2865b115d274d:"
+        }
+      ]
+    },
+    {
+      "id": "claim_ccc0ba3dd45945a5a660a34a678a3f16",
+      "statement": "The repository is Go module github.com/smallstep/cli with go directive 1.25.8.",
+      "evidence": [
+        {
+          "resource": "repo://go.mod#L1-L3",
+          "version": "repo-lines-v1:sha256:68db9910c00dddfb77471b73767aebb727a22031374f6114d77442e632e09181:"
+        }
+      ]
+    },
+    {
+      "id": "claim_5a929439223147fc9ef5608452b713d8",
+      "statement": "Top-level command packages register a cli.Command in init() via cli-utils/command's command.Register and are enabled by blank imports in internal/cmd/root.go, then collected with command.Retrieve().",
+      "evidence": [
+        {
+          "resource": "repo://command/ca/ca.go#L15-L89",
+          "version": "repo-lines-v1:sha256:0155c6100628571b21b7f4f6220d34e98bece60881d19db65fe938face5a95f6:"
+        },
+        {
+          "resource": "repo://internal/cmd/root.go#L30-L44",
+          "version": "repo-lines-v1:sha256:f9fa64bb672657064979bc070b7384bed68f5506a51a855e664a942f483aa20e:"
+        }
+      ]
+    },
+    {
+      "id": "claim_ac3263f528f04fde873b590fba73bacb",
+      "statement": "The Makefile builds github.com/smallstep/cli/cmd/step and injects Version and BuildTime via -ldflags into the main package variables.",
+      "evidence": [
+        {
+          "resource": "repo://Makefile#L126-L132",
+          "version": "repo-lines-v1:sha256:c3fe8335834d25c45d170b1e411c377205dc58bc712e37df0f61b416fb7b6ad5:"
+        }
+      ]
+    },
+    {
+      "id": "claim_ad32ec0a94674e1c9d0adcf04e3a9491",
+      "statement": "The step certificate command group bundles create, sign, inspect, verify, lint, bundle, format, key, install/uninstall, p12, fingerprint, and needsRenewal subcommands.",
+      "evidence": [
+        {
+          "resource": "repo://command/certificate/certificate.go#L84-L98",
+          "version": "repo-lines-v1:sha256:ff67545bb373150b5b94a5a1bcb6e744cdd5234c3382512888f92d40d6ae8cb6:"
+        }
+      ]
+    },
+    {
+      "id": "claim_ba0203f5a37947a199afe1821bb918c6",
+      "statement": "The step ca command group provides init, bootstrap, token, certificate, rekey, renew, revoke, sign, root/roots, federation, health, and the provisioner, admin, policy, and acme subcommand trees.",
+      "evidence": [
+        {
+          "resource": "repo://command/ca/ca.go#L68-L85",
+          "version": "repo-lines-v1:sha256:8230a6d6d09ba737c95661e68d3241c2f6da71f6cbebb101c45d273998dad1b3:"
+        }
+      ]
+    },
+    {
+      "id": "claim_b7be6da70c7146cda91c6f5a905dcdfe",
+      "statement": "The step ssh command group provides certificate, checkHost, config, fingerprint, hosts, inspect, list, login, logout, needsRenewal, proxycommand, rekey, renew, and revoke subcommands.",
+      "evidence": [
+        {
+          "resource": "repo://command/ssh/ssh.go#L84-L100",
+          "version": "repo-lines-v1:sha256:7752286f4b2f4e0d192e14c8a3b6d67aab648f4b75fe8f2059d33d4455c89464:"
+        }
+      ]
+    },
+    {
+      "id": "claim_50ce5a78cd24438f936eefd11bf60e12",
+      "statement": "The step oauth command implements OAuth 2.0 authorization flows and is registered as a top-level command.",
+      "evidence": [
+        {
+          "resource": "repo://command/oauth/cmd.go#L79-L103",
+          "version": "repo-lines-v1:sha256:4b88e3e9c2e2fcae39b8fa6c2e098db6a549e07e435c73ac8d3f38ee6b508e02:"
+        }
+      ]
+    },
+    {
+      "id": "claim_f2cbc560b474472aa0dce739bf1e2b6a",
+      "statement": "The utils/cautils package owns CA client construction, exposing the CaClient interface and switching between an offline CA (via --offline + --ca-config) and an online ca.NewClient.",
+      "evidence": [
+        {
+          "resource": "repo://utils/cautils/client.go#L29-L74",
+          "version": "repo-lines-v1:sha256:4b050a3ee6f5b50d8e156dd76c0856353952096be91258fb2d408ba25bb01969:"
+        }
+      ]
+    },
+    {
+      "id": "claim_8ccbb5dd4abe4d3db6313c9601f9c669",
+      "statement": "KMS-backed keys and attestation are delegated to the step-kms-plugin executable, looked up by internal/plugin and invoked by internal/cryptoutil.CreateSigner.",
+      "evidence": [
+        {
+          "resource": "repo://internal/cryptoutil/cryptoutil.go#L74-L87",
+          "version": "repo-lines-v1:sha256:6227ae682a79b05fd89ca79cd6a3be28f1059fc79ea97aef358c6200addb14ba:"
+        },
+        {
+          "resource": "repo://internal/plugin/plugin.go#L74-L82",
+          "version": "repo-lines-v1:sha256:e343acce7ca6f58483aa97b627b886e14ebcaaaf46a5fd6387e6d7370b78739b:"
+        }
+      ]
+    }
+  ],
+  "verification": {
+    "by": "openwiki/0.4.3",
+    "at": "2026-08-31T03:41:54.605Z"
+  }
+}

Index: openwiki/.claims/commands/crypto.json
===================================================================
--- openwiki/.claims/commands/crypto.json	
+++ openwiki/.claims/commands/crypto.json	
@@ -0,0 +1,118 @@
+{
+  "schemaVersion": 1,
+  "pageVersion": "sha256:e11e8d6e35a50f73ad6cec8de9832b40de9536ca3f9d4977dc749b7dbaebfa89",
+  "claims": [
+    {
+      "id": "claim_f4d6bc1d315440698ad43583ca00867f",
+      "statement": "The step crypto command group registers change-pass, create-key-pair, jwk, jwt, jwe, jws, jose, hash, kdf, key, nacl, otp, rand, and winpe subcommands.",
+      "evidence": [
+        {
+          "resource": "repo://command/crypto/crypto.go#L160-L176",
+          "version": "repo-lines-v1:sha256:a95c8d0e806484bd28b058c532b20a1b447469a68b4683b2445005ce0a78e82e:"
+        }
+      ]
+    },
+    {
+      "id": "claim_5be3997429054fd08b96e89aae93347b",
+      "statement": "step crypto documents a security policy that gates insecure or subtle operations behind --insecure/--subtle, enforces minimum key sizes (256-bit symmetric, 2048-bit RSA), defaults EC to P-256, and notes Ed25519 as the only safe curve.",
+      "evidence": [
+        {
+          "resource": "repo://command/crypto/crypto.go#L39-L159",
+          "version": "repo-lines-v1:sha256:d7a9580d240fba7984d789d9f56606483867014f470b9dfd471362ce06be8e11:"
+        }
+      ]
+    },
+    {
+      "id": "claim_6ddc63312b9f4baebbe2a8cb6c12db6c",
+      "statement": "The default key parameters across the CLI are RSA 2048 bits and EC curve P-256.",
+      "evidence": [
+        {
+          "resource": "repo://utils/cli.go#L12-L16",
+          "version": "repo-lines-v1:sha256:5505a3cbf2519e0330b3004c81506bd94086f5e969f98759bdc191e59ae09d33:"
+        }
+      ]
+    },
+    {
+      "id": "claim_0df2acf1cd374142874d5d7e195c962e",
+      "statement": "step crypto jwt provides sign, verify, and inspect subcommands operating on compact JWS-serialized JWTs with the go.step.sm/crypto/jose library.",
+      "evidence": [
+        {
+          "resource": "repo://command/crypto/jwt/jwt.go#L8-L106",
+          "version": "repo-lines-v1:sha256:6cb83b3a73d40d08d95f6c108ed1582953d2ea048630d2ac44e0134f154537a3:"
+        }
+      ]
+    },
+    {
+      "id": "claim_3160eb4f670a4912982b9a7487312fa1",
+      "statement": "step crypto jwk provides create, keyset (add/list/find/remove), public, and thumbprint subcommands for JWKs and JWK Sets per RFC 7517.",
+      "evidence": [
+        {
+          "resource": "repo://command/crypto/jwk/jwk.go#L6-L94",
+          "version": "repo-lines-v1:sha256:a5154a090b4b915497ed7c4ca26ebf8116f1be489d486672f0d749ee3b7da61d:"
+        }
+      ]
+    },
+    {
+      "id": "claim_a65588f7693642a7999134833f223182",
+      "statement": "step crypto kdf provides hash and compare subcommands over internal/kdf, which implements scrypt (N=32768, r=8, p=1), bcrypt (cost 10), argon2i (m=32768, t=3, p=4), and argon2id (m=65536, t=1, p=4).",
+      "evidence": [
+        {
+          "resource": "repo://command/crypto/kdf/kdf.go#L91-L95",
+          "version": "repo-lines-v1:sha256:1a47107f97901ab68d9d3fdc66194b0d5e88655caa06b4687574a83b738c7f04:"
+        },
+        {
+          "resource": "repo://internal/kdf/kdf.go#L24-L83",
+          "version": "repo-lines-v1:sha256:d01de65565663b28f19a8476438d79b11c57084f5ef6f215e661c2be172f3759:"
+        }
+      ]
+    },
+    {
+      "id": "claim_36efd8a4a9a94aaf8fe72722e38663db",
+      "statement": "kdf.Compare decodes the PHC-encoded hash to discover the algorithm and parameters, recomputes the hash, and compares with a constant-time comparison.",
+      "evidence": [
+        {
+          "resource": "repo://internal/kdf/kdf.go#L88-L130",
+          "version": "repo-lines-v1:sha256:cd1a1e47759fab8ff3ad3ce4da0f57b249f5b78526b8a70d89e574f156e6bcf1:"
+        }
+      ]
+    },
+    {
+      "id": "claim_0745e28c69634753908f125c0522395f",
+      "statement": "KDF parameter parsers bound values to avoid excessive memory use: scrypt ln <= 20, r <= 32, p <= 32, and argon2 m <= 16 GiB, t <= 128, p <= 32.",
+      "evidence": [
+        {
+          "resource": "repo://internal/kdf/argon2.go#L15-L28",
+          "version": "repo-lines-v1:sha256:47331001caed54827414ad6a19d140bab9c94a44fc985fd4bf7972b179dd2fce:"
+        },
+        {
+          "resource": "repo://internal/kdf/scrypt.go#L18-L29",
+          "version": "repo-lines-v1:sha256:2274029a62d51d33385046d38a0d1a2fbca04a4a354290fad26694dd1e29bbef:"
+        }
+      ]
+    },
+    {
+      "id": "claim_037b5cd6499f41228d00927e244c7d16",
+      "statement": "step crypto kdf hash reads the secret from STDIN or a prompt by default and requires the --insecure flag when the secret is passed as a positional argument.",
+      "evidence": [
+        {
+          "resource": "repo://command/crypto/kdf/kdf.go#L160-L203",
+          "version": "repo-lines-v1:sha256:3d055d816995d0fbddffc800f7374808324003d8a496cfe55331c0e7cec6666a:"
+        }
+      ]
+    },
+    {
+      "id": "claim_7ee0224866ae457b875ccef4a4ed64da",
+      "statement": "The winpe subcommand inspects Windows Portable Executable (PE) binaries, supporting attestation of Windows devices.",
+      "evidence": [
+        {
+          "resource": "repo://command/crypto/winpe/winpe.go",
+          "version": "repo-file-v1:sha256:cd3d55a86adc64cc88bbd3d3c6bbe7f1b018546f6a5dc9851b435d9628d2b848"
+        }
+      ]
+    }
+  ],
+  "verification": {
+    "by": "openwiki/0.4.3",
+    "at": "2026-08-31T03:41:54.605Z"
+  }
+}

