			assert.FatalError(t, err)

			phc, err = tc.kdf([]byte(str))
			assert.HasPrefix(t, phc, tc.prefix)
			assert.FatalError(t, err)

			ok, err = CompareString(str, phc)
			assert.True(t, ok)
			assert.NoError(t, err)
		}
	}
}

